def rattacher_aux_campagnes(apps, schema_editor):
    """Les fiches existantes sont rattachées à la dernière campagne ; leur volume vaut fonctionnaires."""
    Campagne = apps.get_model("personnel", "CampagneBesoin")
    Fiche = apps.get_model("personnel", "FicheBesoin")
    campagne = Campagne.objects.order_by("-exercice").first()
    for fiche in Fiche.objects.all():
        fiche.campagne = campagne
        fiche.fonctionnaires = fiche.volume
        fiche.save(update_fields=["campagne", "fonctionnaires"])


